// Package webassets owns the production browser bundle embedded in moment.
package webassets

import (
	"embed"
	"io/fs"
)

// dist is generated by the pinned Web build before any Go build or test.
//
//go:embed dist
var bundled embed.FS

// Public returns the immutable production asset tree rooted at dist.
func Public() (fs.FS, error) {
	return fs.Sub(bundled, "dist")
}
